import{_ as t,c as a,g as l,o as n}from"./chunks/framework.CCxIPCIe.js";const m=JSON.parse('{"title":"四三九","description":"","frontmatter":{"title":"四三九","date":"2026-10-21T13:20:08.929Z","length":"849字","time":"3分钟","aside":false,"hash":1238311881},"headers":[],"relativePath":"idea/439.md","filePath":"idea/439.md"}'),i={name:"idea/439.md"};function s(o,e,r,d,u,c){return n(),a("div",null,e[0]||(e[0]=[l("p",null,"毕业了。期间也经历了许多痛苦，好在还是坚持下来了。写一点读博心得体会吧。",-1),l("ol",null,[l("li",null,"读博需要三重余裕：时间、金钱、社会关系（这条是拾未明子关于自学哲学三重余裕的牙慧）"),l("li",null,"不要美化未曾涉足的另一条道路"),l("li",null,"不要在心烦意乱的时候做重大决定"),l("li",null,"不要以为必须先获得某种身份，然后才配做某件事。因此，不要执迷于某种身份，特别是不要为了追逐这层身份，而忘却了真正的目标，延宕你的欲望和行动。"),l("li",null,"这世界上不存在唯一重要的事情，特别是似乎茧房里所有人都这么觉得的时候。他们觉得重要，并不意味着对你而言重要。他们觉得重要，完全有可能是因为他们慌张而不知所措（他们只是需要把焦虑排解给其他人，以达成精神装置的内稳态，这是符号系统的狡计，不是什么个人的过错）。他们只是人多而已，而你有自己、亲友和亿万个脑细胞在内省。"),l("li",null,"因此，不要把生活锚定在一个唯一的目的上，仿佛得到它就得到了全部，失去它就一文不名。每个人都有自己的生活，过好自己的生活，而不是过好别人口中的生活。唯一值得遗憾的事，是深陷宏大叙事而忽略了你最亲密的关系，并把这种亲密关系视为理所当然的东西。不要让意识形态的漩涡抽走你一切的个人情感，你的感性、脆弱、柔软、暧昧、私密的东西。唯一卑劣的事是用某种总体性（如通用符号）去抹杀个人价值，用某种对生活单一的想象（如一切为了符号增殖）去抹杀多样性。想增殖的人增殖，想喝大水的人喝大水，想撸猫的撸猫，想%？！@的%？！@，和而不同。"),l("li",null,"人的注意是有限的。绝大部分时候，人只是也只能关注自己的生活，并没有余力关注别人的生活。所以不必刻意争取他人的注意，也不必为自己被忽视而介怀。（所以只需要在意在意的人，被在意的人在意就够了。情情而非情不情。）他算老几？你算老几？他就算再了不起，也不过是受到符号系统的眷顾而已，并没有什么神性，而符号系统也并不公平。他迟早会死，你也一样，符号界是迟早要消散的东西，人人死而平等。大家都是萍水相逢而已，只为这种相逢感到庆幸。"),l("li",null,"把每天都当成最后一天，想做什么就做，第二天就未必有机会了。同样，这一天也死而无憾了，被谁在乎不在乎也没什么重要，不过都化成一缕烟散尽了。当然啥也不想做也行，静静的等待死亡。节约时间有时候反而是浪费生命，毕竟你节约的未必是你自己的生命，而是以浪费自己生命为代价。可与不可，做与不做，存乎一心。")],-1)]))}const _=t(i,[["render",s]]);export{m as __pageData,_ as default};
